base:
/* ============================================================================
 * waki-themes / base.css
 * ----------------------------------------------------------------------------
 * Shared fundamentals every theme inherits: typography reset, font stack,
 * the .dark / .light class contract for dark-mode toggling, and a small set
 * of utility classes that the demo HTML uses regardless of which theme is
 * active. Each theme file (flat.css / glass-v1.css / glass-v2.css) layers
 * on top — they only override what's visually distinct.
 * ============================================================================ */

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap");

*,
*::before,
*::after {
  box-sizing: border-box;
}

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

html { color-scheme: light; }
html.dark { color-scheme: dark; }

/* Theme switcher pill — sits floating top-right, semi-transparent so it
   reads on any theme. Picked-state button uses a vivid sky tint so the
   active theme is unmistakable. */
.switcher {
  position: fixed;
  top: 0.75rem;
  right: 0.75rem;
  z-index: 60;
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.25rem;
  padding: 0.3rem 0.4rem;
  border-radius: 1.25rem;
  font-size: 0.75rem;
  font-weight: 500;
  user-select: none;
  /* Cap the width so 18 theme buttons wrap to 2-3 rows instead of
     extending across the whole viewport. The pill stays anchored
     top-right and grows downward. */
  max-width: min(540px, calc(100vw - 1.5rem));
}
.switcher button {
  appearance: none;
  border: 0;
  background: transparent;
  color: inherit;
  padding: 0.3rem 0.7rem;
  border-radius: 9999px;
  cursor: pointer;
  font-size: inherit;
  font-family: inherit;
  font-weight: 600;
  transition: background-color 150ms ease-out;
}
.switcher button:hover { background-color: rgba(0, 0, 0, 0.05); }
html.dark .switcher button:hover { background-color: rgba(255, 255, 255, 0.08); }
.switcher button.active {
  background: linear-gradient(135deg, #6366f1, #ec4899);
  color: white;
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.4);
}
.switcher .divider {
  width: 1px;
  height: 1.1rem;
  background-color: currentColor;
  opacity: 0.25;
  margin: 0 0.25rem;
}

glass-v2.css:
/* ============================================================================
 * waki-themes / glass-v2.css
 * ----------------------------------------------------------------------------
 * Glass theme v2 — everything from v1 plus four layers of polish:
 *   1. SVG fractal-noise texture overlay on the page bg, so the
 *      backdrop-filter has real grain to refract.
 *   2. ::after light glint on each glass card — top-left fade
 *      gradient that reads like a light source catching the surface.
 *   3. Hover treatment that brightens the card slightly with a
 *      smooth 200ms transition, like glass catching light when you
 *      look straight on.
 *   4. Slow `gradientShift` animation on the body bg-position so the
 *      gradient drifts under the glass surfaces. 30s cycle — barely
 *      perceptible but enough to keep the surfaces from feeling
 *      static. Disabled under prefers-reduced-motion.
 * ============================================================================ */

/* ----- Page background + drift animation ------------------------------- */
body {
  background: linear-gradient(135deg, #e8eef5 0%, #f0f4f9 30%, #e5edf6 60%, #eef2f8 100%);
  background-attachment: fixed;
  background-size: 200% 200%;
  animation: gradientShift 30s ease-in-out infinite;
  color: #0f172a;
}
html.dark body {
  background: linear-gradient(135deg, #0c1220 0%, #162033 30%, #1a2744 60%, #0f1a2e 100%);
  background-attachment: fixed;
  background-size: 200% 200%;
  animation: gradientShift 30s ease-in-out infinite;
  color: #f1f5f9;
}

@keyframes gradientShift {
  0%   { background-position: 0% 0%; }
  50%  { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}

/* SVG fractal-noise grain overlay. Inlined as a data URI so this CSS
   file is fully self-contained — drop it in any project, no asset
   pipeline needed. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  opacity: 0.03;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
  pointer-events: none;
}
html.dark body::before {
  opacity: 0.04;
}

/* ----- Surfaces --------------------------------------------------------- */
/* `position: relative` here so the absolute ::after glint positions
   against the card itself, not some distant ancestor. */
.glass {
  position: relative;
  background: rgba(255, 255, 255, 0.65);
  backdrop-filter: blur(12px) saturate(150%);
  -webkit-backdrop-filter: blur(12px) saturate(150%);
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 0.875rem;
  box-shadow: 0 8px 32px rgba(15, 23, 42, 0.08);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
}

.glass-elevated {
  position: relative;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 0.875rem;
  box-shadow: 0 12px 40px rgba(15, 23, 42, 0.1);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass-elevated {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.15);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
}

/* Light glint — top-left highlight that traces the card outline.
   border-radius: inherit makes it follow whatever radius the host
   card has, so the same rule works on a pill / rounded-xl / square
   card without per-element overrides. pointer-events: none so it
   never catches taps. */
.glass::after,
.glass-elevated::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.18) 0%, transparent 50%);
  pointer-events: none;
}
html.dark .glass::after,
html.dark .glass-elevated::after {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.1) 0%, transparent 50%);
}

/* Hover — slightly more opaque + deeper drop shadow, like real glass
   brightening when you look at it straight on. */
.glass:hover {
  background: rgba(255, 255, 255, 0.75);
  box-shadow: 0 12px 40px rgba(15, 23, 42, 0.12);
}
html.dark .glass:hover {
  background: rgba(255, 255, 255, 0.1);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
}
.glass-elevated:hover {
  background: rgba(255, 255, 255, 0.88);
  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.14);
}
html.dark .glass-elevated:hover {
  background: rgba(255, 255, 255, 0.14);
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.4);
}

.glass-bar {
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(18px) saturate(160%);
  -webkit-backdrop-filter: blur(18px) saturate(160%);
}
html.dark .glass-bar {
  background: rgba(15, 23, 42, 0.55);
}

.chip {
  background: rgba(255, 255, 255, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
html.dark .chip {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);
}

.divider-soft {
  border-color: rgba(15, 23, 42, 0.08);
}
html.dark .divider-soft {
  border-color: rgba(255, 255, 255, 0.08);
}

/* Honour user motion preferences. The drifting page gradient is the
   exact kind of background motion that triggers vestibular discomfort
   for some users. */
@media (prefers-reduced-motion: reduce) {
  body {
    animation: none !important;
  }
}

glass-v1.css:
/* ============================================================================
 * waki-themes / glass-v1.css
 * ----------------------------------------------------------------------------
 * Glass theme v1 — frosted glass surfaces over a soft gradient page.
 * Translucent backgrounds with `backdrop-filter` blur so layered cards
 * compose visible depth. No texture, no glints, no motion — just clean
 * frosted panels.
 *
 * Browser support: backdrop-filter works everywhere except very old
 * Safari versions. On unsupported browsers the panels still render —
 * the rgba background just shows the gradient through clearly without
 * the blur, which still looks acceptable.
 * ============================================================================ */

/* ----- Page background -------------------------------------------------- */
/* Soft cool-grey gradient in light mode, deep navy gradient in dark.
   `background-attachment: fixed` so the gradient stays put while content
   scrolls — a moving gradient drags attention every scroll. */
body {
  background: linear-gradient(135deg, #e8eef5 0%, #f0f4f9 30%, #e5edf6 60%, #eef2f8 100%);
  background-attachment: fixed;
  color: #0f172a;
}
html.dark body {
  /* Violet/indigo undertone in dark mode so glass-v1 reads as warmer
     than glass-v2's cool blue baseline. Same brightness floor; the
     difference is hue, not luminosity. */
  background: linear-gradient(135deg, #170c2a 0%, #251447 30%, #1f1240 60%, #14092a 100%);
  background-attachment: fixed;
  color: #f1f5f9;
}

/* ----- Surfaces --------------------------------------------------------- */
.glass {
  background: rgba(255, 255, 255, 0.65);
  backdrop-filter: blur(12px) saturate(150%);
  -webkit-backdrop-filter: blur(12px) saturate(150%);
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 0.875rem;
  box-shadow: 0 8px 32px rgba(15, 23, 42, 0.08);
  transition: background-color 150ms ease-out, box-shadow 150ms ease-out;
}
html.dark .glass {
  /* Violet-tinted panel chroma so v1 stays visibly its own theme even
     in dark mode. Was rgba(255,255,255,0.06) which converged with v2. */
  background: rgba(168, 85, 247, 0.09);
  border-color: rgba(168, 85, 247, 0.22);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
}

.glass-elevated {
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 0.875rem;
  box-shadow: 0 12px 40px rgba(15, 23, 42, 0.1);
  transition: background-color 150ms ease-out, box-shadow 150ms ease-out;
}
html.dark .glass-elevated {
  background: rgba(168, 85, 247, 0.13);
  border-color: rgba(168, 85, 247, 0.3);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
}

/* Frosted bar — used by fixed Header / sidebar chrome. Slightly more
   blur than .glass so the chrome reads as "behind the content" even
   when content scrolls past it. */
.glass-bar {
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(18px) saturate(160%);
  -webkit-backdrop-filter: blur(18px) saturate(160%);
}
html.dark .glass-bar {
  background: rgba(31, 18, 64, 0.6);
}

.chip {
  background: rgba(255, 255, 255, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
html.dark .chip {
  background: rgba(168, 85, 247, 0.1);
  border-color: rgba(168, 85, 247, 0.22);
}

.divider-soft {
  border-color: rgba(15, 23, 42, 0.08);
}
html.dark .divider-soft {
  border-color: rgba(255, 255, 255, 0.08);
}

glass-v3.css:
/* ============================================================================
 * Theme: glass-v3 — Aurora glass
 * ----------------------------------------------------------------------------
 * Coloured tinted glass over a multi-stop aurora-blob background. Heavier
 * 20px blur than glass-v2 so the colours behind dissolve into a soft
 * watercolour wash; cards carry a violet/cyan tint instead of pure
 * white. Each card has a gradient border drawn via ::before so the
 * outline reads as a thin ribbon of refracted light.
 * ============================================================================ */

/* ----- Page background — aurora blobs over a soft gradient -------------- */
body {
  background:
    radial-gradient(ellipse at 12% 18%, rgba(168, 85, 247, 0.18), transparent 50%),
    radial-gradient(ellipse at 88% 78%, rgba(34, 211, 238, 0.18), transparent 50%),
    radial-gradient(ellipse at 50% 110%, rgba(236, 72, 153, 0.12), transparent 55%),
    linear-gradient(135deg, #f4ecff 0%, #ecf6ff 50%, #fff5fb 100%);
  background-attachment: fixed;
  color: #1e1b4b;
}
html.dark body {
  background:
    radial-gradient(ellipse at 12% 18%, rgba(139, 92, 246, 0.32), transparent 50%),
    radial-gradient(ellipse at 88% 78%, rgba(14, 165, 233, 0.30), transparent 50%),
    radial-gradient(ellipse at 50% 110%, rgba(236, 72, 153, 0.22), transparent 55%),
    linear-gradient(135deg, #0a0517 0%, #0a1424 50%, #110820 100%);
  background-attachment: fixed;
  color: #ede9fe;
}

/* ----- Surfaces --------------------------------------------------------- */
/* Position relative so the gradient-border ::before positions correctly.
   The bg uses a violet tint instead of pure white; with 20px blur the
   colours behind the card mix into the violet for an aurora-haze
   look. */
.glass {
  position: relative;
  background: rgba(168, 85, 247, 0.08) !important;
  backdrop-filter: blur(20px) saturate(200%);
  -webkit-backdrop-filter: blur(20px) saturate(200%);
  border: 1px solid transparent;
  border-radius: 1rem;
  box-shadow: 0 8px 32px rgba(76, 29, 149, 0.15);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass {
  background: rgba(168, 85, 247, 0.07) !important;
  border-color: transparent;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

.glass-elevated {
  position: relative;
  background: rgba(255, 255, 255, 0.65) !important;
  backdrop-filter: blur(24px) saturate(220%);
  -webkit-backdrop-filter: blur(24px) saturate(220%);
  border: 1px solid transparent;
  border-radius: 1rem;
  box-shadow: 0 16px 48px rgba(76, 29, 149, 0.18);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass-elevated {
  background: rgba(139, 92, 246, 0.12) !important;
  box-shadow: 0 16px 56px rgba(0, 0, 0, 0.6);
}

/* Gradient border via ::before. The mask-composite trick paints the
   gradient only on the 1px frame — content area stays untouched. The
   gradient cycles violet → cyan → pink so the border reads as
   refracted aurora light. */
.glass::before,
.glass-elevated::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    135deg,
    rgba(168, 85, 247, 0.6) 0%,
    rgba(34, 211, 238, 0.5) 50%,
    rgba(236, 72, 153, 0.6) 100%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  pointer-events: none;
}
html.dark .glass::before,
html.dark .glass-elevated::before {
  background: linear-gradient(
    135deg,
    rgba(167, 139, 250, 0.5) 0%,
    rgba(34, 211, 238, 0.4) 50%,
    rgba(244, 114, 182, 0.5) 100%
  );
}

.glass:hover {
  background: rgba(168, 85, 247, 0.12) !important;
  box-shadow: 0 12px 40px rgba(76, 29, 149, 0.22);
}
html.dark .glass:hover {
  background: rgba(168, 85, 247, 0.12) !important;
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.55);
}
.glass-elevated:hover {
  box-shadow: 0 20px 56px rgba(76, 29, 149, 0.25);
}
html.dark .glass-elevated:hover {
  box-shadow: 0 20px 64px rgba(0, 0, 0, 0.65);
}

.glass-bar {
  background: rgba(255, 255, 255, 0.55) !important;
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
}
html.dark .glass-bar {
  background: rgba(15, 12, 41, 0.6) !important;
}

.chip {
  background: rgba(168, 85, 247, 0.08);
  border: 1px solid rgba(168, 85, 247, 0.2);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
html.dark .chip {
  background: rgba(167, 139, 250, 0.08);
  border-color: rgba(167, 139, 250, 0.2);
}

.divider-soft {
  border-color: rgba(76, 29, 149, 0.12);
}
html.dark .divider-soft {
  border-color: rgba(167, 139, 250, 0.15);
}

glass-extreme.css:
/* ============================================================================
 * Theme: glass-extreme — iOS / macOS-style ultra-translucent vibrant glass
 * ----------------------------------------------------------------------------
 * The most translucent / heaviest-blur theme in the set. Tuned to feel
 * like Big Sur Control Centre or an iOS lock-screen widget: cards
 * disappear into the background until you almost can't tell where they
 * end, but the heavy blur + saturate / brightness boost keeps the
 * contents legible.
 *
 * Distinct from the other glass themes:
 *   glass-v1 / v2  — 12-16px blur, opaque-ish white tints
 *   glass-v3       — 20px blur, coloured aurora tints + gradient borders
 *   glass-extreme  — 40px blur, near-invisible white, vibrancy bumped via
 *                    saturate(200%) + brightness(110%), hairline 0.5px
 *                    borders only, very wide soft shadows, generous
 *                    rounded corners, slow 60s gradient drift
 *
 * No noise overlay, no glint pseudo-element — iOS doesn't use either.
 * The vibrancy effect alone carries the look. */

/* ----- Page background — iOS wallpaper-style multi-stop gradient ------- */
/* Light mode: a soft sky-blue / pink / lavender wash. Dark mode: deep
   navy → indigo → purple. Both bgs animate the gradient position over
   60s so the colours behind the glass shift slowly — the cards refract
   different tones during the day. */
body {
  background: linear-gradient(
    135deg,
    #c7d2fe 0%,
    #ddd6fe 25%,
    #fbcfe8 50%,
    #c4b5fd 75%,
    #a5b4fc 100%
  );
  background-attachment: fixed;
  background-size: 240% 240%;
  animation: glassExtremeDrift 60s ease-in-out infinite;
  color: rgba(15, 23, 42, 0.9);
}
html.dark body {
  background: linear-gradient(
    135deg,
    #0f172a 0%,
    #1e1b4b 25%,
    #3b0764 50%,
    #1e1b4b 75%,
    #0f172a 100%
  );
  background-attachment: fixed;
  background-size: 240% 240%;
  animation: glassExtremeDrift 60s ease-in-out infinite;
  color: rgba(241, 245, 249, 0.9);
}
@keyframes glassExtremeDrift {
  0%, 100% { background-position: 0% 50%; }
  50%      { background-position: 100% 50%; }
}
@media (prefers-reduced-motion: reduce) {
  body { animation: none !important; }
}

/* ----- Surfaces -------------------------------------------------------- */
/* The 0.5px hairline borders are drawn via inset box-shadow rather than a
   real `border` because iOS draws them sub-pixel and a real `border:
   0.5px` has been observed to render as 1px on many displays. The
   inset-shadow trick honours subpixel widths reliably. */
.glass, .card {
  background: rgba(255, 255, 255, 0.45) !important;
  backdrop-filter: blur(40px) saturate(200%) brightness(110%);
  -webkit-backdrop-filter: blur(40px) saturate(200%) brightness(110%);
  border: none !important;
  border-radius: 1.25rem !important;
  box-shadow:
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.5),
    0 20px 60px -10px rgba(15, 23, 42, 0.12) !important;
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out, opacity 150ms ease-out;
}
html.dark .glass, html.dark .card {
  background: rgba(255, 255, 255, 0.15) !important;
  box-shadow:
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.18),
    0 20px 60px -10px rgba(0, 0, 0, 0.4) !important;
}

/* Hover: brightens the glass — opacity ticks up, hairline brightens.
   No translateY, no scale; this should feel like the surface catching
   more light, not bouncing. */
.glass:hover, .card:hover {
  background: rgba(255, 255, 255, 0.55) !important;
  box-shadow:
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.65),
    0 24px 70px -10px rgba(15, 23, 42, 0.18) !important;
}
html.dark .glass:hover, html.dark .card:hover {
  background: rgba(255, 255, 255, 0.22) !important;
  box-shadow:
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.28),
    0 24px 70px -10px rgba(0, 0, 0, 0.5) !important;
}

/* Active: dims slightly so the surface looks "pressed" without the
   sharp corner highlight that a real button would have. */
.glass:active, .card:active {
  background: rgba(255, 255, 255, 0.38) !important;
}
html.dark .glass:active, html.dark .card:active {
  background: rgba(255, 255, 255, 0.12) !important;
}

/* glass-elevated sits visually on top of .glass — slightly stronger
   tint + heavier blur so when stacked the layers feel distinct. iOS
   Control Centre uses this exact "glass on glass on background" depth
   trick. */
.glass-elevated, .card-elevated {
  background: rgba(255, 255, 255, 0.55) !important;
  backdrop-filter: blur(50px) saturate(220%) brightness(115%);
  -webkit-backdrop-filter: blur(50px) saturate(220%) brightness(115%);
  border: none !important;
  border-radius: 1.25rem !important;
  box-shadow:
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.6),
    0 28px 80px -10px rgba(15, 23, 42, 0.15) !important;
}
html.dark .glass-elevated, html.dark .card-elevated {
  background: rgba(255, 255, 255, 0.22) !important;
  box-shadow:
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.25),
    0 28px 80px -10px rgba(0, 0, 0, 0.5) !important;
}
.glass-elevated:hover, .card-elevated:hover {
  background: rgba(255, 255, 255, 0.65) !important;
}
html.dark .glass-elevated:hover, html.dark .card-elevated:hover {
  background: rgba(255, 255, 255, 0.28) !important;
}

/* glass-bar is the chrome strip — heaviest blur of all so the top /
   bottom of the page reads as a permanent frosted band you scroll the
   content under. */
.glass-bar {
  background: rgba(255, 255, 255, 0.55) !important;
  backdrop-filter: blur(60px) saturate(180%) brightness(108%);
  -webkit-backdrop-filter: blur(60px) saturate(180%) brightness(108%);
  border-bottom: none !important;
  box-shadow: inset 0 -0.5px 0 rgba(255, 255, 255, 0.4) !important;
}
html.dark .glass-bar {
  background: rgba(255, 255, 255, 0.12) !important;
  box-shadow: inset 0 -0.5px 0 rgba(255, 255, 255, 0.15) !important;
}

/* Surface helpers — keep them transparent so the body gradient shows
   through. Cards / chrome do all the depth work; the page wrapper
   itself stays out of the way. */
.surface-page, .surface-1, .surface-2, .surface-3, .surface-muted {
  background-color: transparent !important;
}

/* iOS-style chip / pill — same hairline trick, same radius family. */
.chip {
  background: rgba(255, 255, 255, 0.4);
  border: none;
  border-radius: 9999px;
  box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.45);
}
html.dark .chip {
  background: rgba(255, 255, 255, 0.12);
  box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.18);
}

/* iOS grouped-table-view divider — hairline 0.5px line, sits on top of
   the card so it doesn't break the rounded outline. */
.divider-soft {
  border-color: rgba(15, 23, 42, 0.08);
  border-width: 0.5px;
}
html.dark .divider-soft {
  border-color: rgba(255, 255, 255, 0.1);
  border-width: 0.5px;
}

.input {
  background: rgba(255, 255, 255, 0.55) !important;
  border: none !important;
  border-radius: 1rem !important;
  box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.5) !important;
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
}
html.dark .input {
  background: rgba(255, 255, 255, 0.15) !important;
  color: rgba(241, 245, 249, 0.95);
  box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.2) !important;
}
.input:focus {
  background: rgba(255, 255, 255, 0.7) !important;
  box-shadow: inset 0 0 0 0.5px rgba(99, 102, 241, 0.6) !important;
}
html.dark .input:focus {
  background: rgba(255, 255, 255, 0.22) !important;
  box-shadow: inset 0 0 0 0.5px rgba(165, 180, 252, 0.7) !important;
}

/* Body text tones — slightly transparent so headings get the contrast
   advantage. iOS typography spec uses 90% / 60% / 30% alpha tiers. */
html.dark .text-body, html.dark .text-subtle, html.dark p {
  color: rgba(241, 245, 249, 0.9);
}

frosted-glass.css:
/* ============================================================================
 * waki-themes / frosted-glass.css
 * ----------------------------------------------------------------------------
 * Frosted Glass — maximum frost everywhere.
 *
 *   - Deep ocean / blue-green page gradient with a 45s drift.
 *   - Ultra-heavy frost (30px blur, 180% saturate) on every surface.
 *   - Teal/cyan-tinted card alphas + borders so the frost reads as
 *     blue-green refracted ocean light, not just neutral white haze.
 *   - Teal-tinted shadows so the floating panels feel like they're sitting
 *     in cool water rather than over a flat black plane.
 * ============================================================================ */

/* ----- Page background + drift animation ------------------------------- */
body {
  background: linear-gradient(135deg, #e0f0f5 0%, #eaf5e8 40%, #dff0f8 100%);
  background-attachment: fixed;
  background-size: 220% 220%;
  animation: frostedGlassDrift 45s ease-in-out infinite;
  color: #0b1f2a;
}
html.dark body {
  background: linear-gradient(135deg, #0a1628 0%, #0d2233 50%, #0a2018 100%);
  background-attachment: fixed;
  background-size: 220% 220%;
  animation: frostedGlassDrift 45s ease-in-out infinite;
  color: #e6f4f1;
}

@keyframes frostedGlassDrift {
  0%   { background-position: 0% 0%; }
  50%  { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}

/* SVG fractal-noise grain overlay so the heavy frost has actual grain
   to refract — without it 30px blur on a flat gradient looks washed-out
   rather than frosty. Inlined as a data URI so this file is portable. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  opacity: 0.025;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
  pointer-events: none;
}
html.dark body::before {
  opacity: 0.035;
}

/* ----- Surfaces --------------------------------------------------------- */
/* `position: relative` so the absolute ::after glint positions against the
   card itself, not some distant ancestor. Card alphas carry a *slight*
   teal tint (a few r/g/b points) so the frost reads as cool ocean haze
   rather than neutral white — the user specifically called out
   blue/green/teal palette, no purple. */
.glass {
  position: relative;
  background: rgba(240, 252, 252, 0.55);
  backdrop-filter: blur(30px) saturate(180%);
  -webkit-backdrop-filter: blur(30px) saturate(180%);
  border: 1px solid rgba(0, 200, 200, 0.18);
  border-radius: 0.875rem;
  box-shadow: 0 8px 32px rgba(0, 100, 100, 0.18);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass {
  background: rgba(0, 180, 180, 0.06);
  border-color: rgba(0, 220, 220, 0.14);
  box-shadow: 0 8px 32px rgba(0, 60, 70, 0.45);
}

.glass-elevated {
  position: relative;
  background: rgba(245, 254, 254, 0.72);
  backdrop-filter: blur(30px) saturate(180%);
  -webkit-backdrop-filter: blur(30px) saturate(180%);
  border: 1px solid rgba(0, 200, 200, 0.22);
  border-radius: 0.875rem;
  box-shadow: 0 16px 48px rgba(0, 100, 100, 0.22);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass-elevated {
  background: rgba(0, 200, 200, 0.10);
  border-color: rgba(0, 220, 220, 0.18);
  box-shadow: 0 16px 48px rgba(0, 50, 60, 0.55);
}

/* Light glint — top-left highlight that traces the card outline. The
   linear gradient picks up just a hint of cyan in light mode so it reads
   as light catching the surface rather than a pure white smear. */
.glass::after,
.glass-elevated::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(220, 250, 250, 0.28) 0%, transparent 55%);
  pointer-events: none;
}
html.dark .glass::after,
html.dark .glass-elevated::after {
  background: linear-gradient(135deg, rgba(150, 230, 230, 0.10) 0%, transparent 55%);
}

/* Hover — slightly more opaque + deeper drop shadow, like real glass
   brightening when you look at it straight on. */
.glass:hover {
  background: rgba(245, 254, 254, 0.65);
  box-shadow: 0 12px 40px rgba(0, 100, 100, 0.24);
}
html.dark .glass:hover {
  background: rgba(0, 200, 200, 0.10);
  box-shadow: 0 12px 40px rgba(0, 60, 70, 0.55);
}
.glass-elevated:hover {
  background: rgba(248, 254, 254, 0.82);
  box-shadow: 0 20px 56px rgba(0, 100, 100, 0.28);
}
html.dark .glass-elevated:hover {
  background: rgba(0, 210, 210, 0.14);
  box-shadow: 0 20px 56px rgba(0, 60, 70, 0.6);
}

/* Top bar / nav — same heavy frost so the header reads as a floating
   pane rather than a hard horizon line. Slight teal cast in dark mode
   for the underwater feel. */
.glass-bar {
  background: rgba(235, 250, 250, 0.6);
  backdrop-filter: blur(30px) saturate(180%);
  -webkit-backdrop-filter: blur(30px) saturate(180%);
  border-bottom: 1px solid rgba(0, 200, 200, 0.15);
}
html.dark .glass-bar {
  background: rgba(8, 28, 38, 0.65);
  border-bottom-color: rgba(0, 220, 220, 0.12);
}

/* Pills / chips — lighter blur but same teal palette so they don't break
   the look when stacked on a frosted card. */
.chip {
  background: rgba(220, 245, 245, 0.45);
  border: 1px solid rgba(0, 200, 200, 0.18);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
html.dark .chip {
  background: rgba(0, 200, 200, 0.06);
  border-color: rgba(0, 220, 220, 0.14);
}

.divider-soft {
  border-color: rgba(0, 100, 100, 0.10);
}
html.dark .divider-soft {
  border-color: rgba(0, 220, 220, 0.10);
}

/* Honour user motion preferences. The drifting page gradient is the
   exact kind of background motion that triggers vestibular discomfort
   for some users. */
@media (prefers-reduced-motion: reduce) {
  body {
    animation: none !important;
  }
}

midnight.css:
/* ============================================================================
 * Theme: midnight — Glowing-edge cards on near-black
 * ----------------------------------------------------------------------------
 * Structurally: cards are ALMOST invisible — same colour as the page
 * bg, no border, no overall shadow. The trick is a one-sided gradient
 * border on the top edge, glowing in deep blue, like light leaking
 * out from behind a panel. Dramatic, moody, theatrical.
 * ============================================================================ */

body {
  background: linear-gradient(180deg, #020617 0%, #050714 50%, #0a0e1c 100%);
  background-attachment: fixed;
  color: #cbd5e1;
}
html.dark body {
  background: linear-gradient(180deg, #020617 0%, #050714 50%, #0a0e1c 100%);
  background-attachment: fixed;
  color: #cbd5e1;
}
/* Light mode of midnight inverts contrast — bright sky-blue on a dark
   navy bg, instead of cyan-blue on near-black. Same dramatic style,
   just rotated. */
html.light body {
  background: linear-gradient(180deg, #1e293b 0%, #1e3a5f 50%, #0f172a 100%);
  background-attachment: fixed;
  color: #f1f5f9;
}

.glass, .card {
  position: relative;
  background: rgba(2, 6, 23, 0.6) !important;
  border: none;
  border-radius: 0.625rem;
  box-shadow: none;
  overflow: hidden;
}
html.light .glass, html.light .card {
  background: rgba(15, 23, 42, 0.5) !important;
}

/* Light-leak: a glowing 2px line along the top edge, fading sideways.
   Cyan/sky-blue glow simulating ambient light bleeding from behind. */
.glass::before, .card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1.5px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(56, 189, 248, 0.3) 15%,
    rgba(125, 211, 252, 0.95) 50%,
    rgba(56, 189, 248, 0.3) 85%,
    transparent 100%
  );
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.6);
  pointer-events: none;
}
/* Bottom edge gets a softer counter-leak — half the brightness, only
   the centre glows. Reads like a panel slightly lit from above and
   below. */
.glass::after, .card::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 20%;
  right: 20%;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(56, 189, 248, 0.3) 50%,
    transparent 100%
  );
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.25);
  pointer-events: none;
}

.glass-elevated, .card-elevated {
  position: relative;
  background: rgba(8, 13, 30, 0.7) !important;
  border: none;
  border-radius: 0.625rem;
  overflow: hidden;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.6);
}
.glass-elevated::before, .card-elevated::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(165, 180, 252, 0.4) 12%,
    rgba(199, 210, 254, 1) 50%,
    rgba(165, 180, 252, 0.4) 88%,
    transparent 100%
  );
  box-shadow: 0 0 18px rgba(199, 210, 254, 0.7);
  pointer-events: none;
}
.glass-elevated::after, .card-elevated::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 15%;
  right: 15%;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(165, 180, 252, 0.4) 50%,
    transparent 100%
  );
  box-shadow: 0 0 10px rgba(165, 180, 252, 0.35);
  pointer-events: none;
}

.glass:hover::before, .card:hover::before {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(56, 189, 248, 0.5) 10%,
    rgba(186, 230, 253, 1) 50%,
    rgba(56, 189, 248, 0.5) 90%,
    transparent 100%
  );
  box-shadow: 0 0 16px rgba(125, 211, 252, 0.85);
}

.glass-bar {
  background: rgba(2, 6, 23, 0.85) !important;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  position: relative;
}
.glass-bar::after {
  content: "";
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(56, 189, 248, 0.6) 50%,
    transparent 100%
  );
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.4);
}

.surface-page, .surface-1, .surface-2, .surface-3, .surface-muted {
  background-color: #020617 !important;
}
html.light .surface-page, html.light .surface-1, html.light .surface-2,
html.light .surface-3, html.light .surface-muted {
  background-color: #0f172a !important;
}

.chip {
  background: rgba(2, 6, 23, 0.7);
  border: 1px solid rgba(56, 189, 248, 0.3);
  color: #cbd5e1;
}
.divider-soft { border-color: rgba(56, 189, 248, 0.18); }
.input {
  background: rgba(2, 6, 23, 0.6) !important;
  border: 1px solid rgba(56, 189, 248, 0.25) !important;
  color: #e2e8f0;
}
.input:focus {
  border-color: rgba(125, 211, 252, 0.7) !important;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.3) !important;
}

neon.css:
/* ============================================================================
 * Theme: neon — Cyberpunk neon
 * ----------------------------------------------------------------------------
 * Near-black bg with bright neon borders and glow. .glass cards take
 * cyan, .glass-elevated takes magenta, .glass-bar takes lime — three
 * distinct neon colours so the visual hierarchy reads at a glance.
 * Each surface has both an outer bloom and a subtle inset glow,
 * mimicking real backlit acrylic signage.
 *
 * A faint horizontal scan-line overlay covers the page (CRT-style)
 * to push the cyberpunk aesthetic without being distracting.
 *
 * Light mode keeps the neon strokes but on a pearl-grey paper bg —
 * cyberpunk-on-paper. Less authentic to the genre but at least
 * legible if the user has a light-mode preference.
 * ============================================================================ */

body {
  background: linear-gradient(180deg, #f7f7fa 0%, #ececf2 100%);
  background-attachment: fixed;
  color: #0a0a0f;
}
html.dark body {
  background: linear-gradient(180deg, #050510 0%, #0c0c1a 50%, #050510 100%);
  background-attachment: fixed;
  color: #e0fbff;
}

/* CRT scan-line overlay. repeating-linear-gradient at 3px stripes,
   very low alpha so the effect is texture, not stripes. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    rgba(255, 255, 255, 0.02) 0px,
    rgba(255, 255, 255, 0.02) 1px,
    transparent 1px,
    transparent 3px
  );
}
html.dark body::before {
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 255, 255, 0.025) 0px,
    rgba(0, 255, 255, 0.025) 1px,
    transparent 1px,
    transparent 3px
  );
}

/* ----- Surfaces --------------------------------------------------------- */
/* Each surface picks a different neon hue so the visual hierarchy is
   colour-coded:
     .glass          → cyan   (#00ffff)
     .glass-elevated → magenta (#ff00ff)
     .glass-bar      → lime    (#aaff00)
   The shadow stack is "outer bloom + inset glow" — outer makes the
   card look lit, inset makes the panel itself seem backlit. */
.glass {
  position: relative;
  background: rgba(255, 255, 255, 0.7) !important;
  border: 1px solid rgba(0, 200, 220, 0.6);
  border-radius: 0.75rem;
  box-shadow:
    0 0 14px rgba(0, 200, 220, 0.3),
    inset 0 0 14px rgba(0, 200, 220, 0.06);
  transition: box-shadow 200ms ease-out, border-color 200ms ease-out;
}
html.dark .glass {
  background: rgba(5, 10, 20, 0.78) !important;
  border-color: #00ffff;
  box-shadow:
    0 0 12px rgba(0, 255, 255, 0.55),
    0 0 28px rgba(0, 255, 255, 0.25),
    inset 0 0 18px rgba(0, 255, 255, 0.08);
}

.glass-elevated {
  position: relative;
  background: rgba(255, 255, 255, 0.78) !important;
  border: 1px solid rgba(220, 50, 200, 0.55);
  border-radius: 0.75rem;
  box-shadow:
    0 0 16px rgba(220, 50, 200, 0.3),
    inset 0 0 16px rgba(220, 50, 200, 0.05);
  transition: box-shadow 200ms ease-out, border-color 200ms ease-out;
}
html.dark .glass-elevated {
  background: rgba(8, 4, 16, 0.82) !important;
  border-color: #ff00ff;
  box-shadow:
    0 0 14px rgba(255, 0, 255, 0.6),
    0 0 32px rgba(255, 0, 255, 0.25),
    inset 0 0 20px rgba(255, 0, 255, 0.08);
}

/* Hover — bloom intensifies and the border saturates. */
.glass:hover {
  border-color: rgba(0, 200, 220, 0.85);
  box-shadow:
    0 0 18px rgba(0, 200, 220, 0.45),
    0 0 32px rgba(0, 200, 220, 0.25),
    inset 0 0 16px rgba(0, 200, 220, 0.1);
}
html.dark .glass:hover {
  box-shadow:
    0 0 18px rgba(0, 255, 255, 0.8),
    0 0 40px rgba(0, 255, 255, 0.4),
    inset 0 0 24px rgba(0, 255, 255, 0.12);
}
.glass-elevated:hover {
  border-color: rgba(220, 50, 200, 0.85);
  box-shadow:
    0 0 20px rgba(220, 50, 200, 0.45),
    0 0 36px rgba(220, 50, 200, 0.25),
    inset 0 0 18px rgba(220, 50, 200, 0.1);
}
html.dark .glass-elevated:hover {
  box-shadow:
    0 0 20px rgba(255, 0, 255, 0.8),
    0 0 44px rgba(255, 0, 255, 0.4),
    inset 0 0 28px rgba(255, 0, 255, 0.14);
}

/* Bar — lime hue. Used on the fixed Header / Breadcrumb so the chrome
   has its own neon stroke distinct from the cards. */
.glass-bar {
  background: rgba(255, 255, 255, 0.85) !important;
  border-bottom: 1px solid rgba(140, 200, 0, 0.55);
  box-shadow: 0 0 14px rgba(140, 200, 0, 0.18);
}
html.dark .glass-bar {
  background: rgba(5, 10, 5, 0.85) !important;
  border-color: #aaff00;
  box-shadow:
    0 0 12px rgba(170, 255, 0, 0.5),
    0 0 24px rgba(170, 255, 0, 0.2);
}

/* Chips: small neon outline with a faint glow. Cycle through cyan in
   dark mode to keep the look cohesive without competing with the
   card hues. */
.chip {
  background: rgba(255, 255, 255, 0.5);
  border: 1px solid rgba(0, 200, 220, 0.5);
  box-shadow: 0 0 6px rgba(0, 200, 220, 0.2);
}
html.dark .chip {
  background: rgba(0, 0, 0, 0.4);
  border-color: rgba(0, 255, 255, 0.6);
  box-shadow: 0 0 6px rgba(0, 255, 255, 0.4);
}

.divider-soft {
  border-color: rgba(0, 200, 220, 0.25);
}
html.dark .divider-soft {
  border-color: rgba(0, 255, 255, 0.25);
}

/* Bulk of the dashboard uses .card / .card-elevated — map them onto the
   same neon-glow look as .glass / .glass-elevated so the cyberpunk
   aesthetic doesn't fall back to slate-800 on >80% of surfaces. */
.card {
  background: rgba(255, 255, 255, 0.7) !important;
  border: 1px solid rgba(0, 200, 220, 0.55) !important;
  border-radius: 0.75rem !important;
  box-shadow:
    0 0 12px rgba(0, 200, 220, 0.25),
    inset 0 0 12px rgba(0, 200, 220, 0.05) !important;
}
html.dark .card {
  background: rgba(5, 10, 20, 0.78) !important;
  border-color: #00ffff !important;
  color: #e0fbff;
  box-shadow:
    0 0 12px rgba(0, 255, 255, 0.5),
    0 0 24px rgba(0, 255, 255, 0.2),
    inset 0 0 16px rgba(0, 255, 255, 0.07) !important;
}
.card-elevated {
  background: rgba(255, 255, 255, 0.78) !important;
  border: 1px solid rgba(220, 50, 200, 0.55) !important;
  border-radius: 0.75rem !important;
  box-shadow:
    0 0 14px rgba(220, 50, 200, 0.3),
    inset 0 0 14px rgba(220, 50, 200, 0.05) !important;
}
html.dark .card-elevated {
  background: rgba(8, 4, 16, 0.82) !important;
  border-color: #ff00ff !important;
  color: #fce7ff;
  box-shadow:
    0 0 14px rgba(255, 0, 255, 0.55),
    0 0 28px rgba(255, 0, 255, 0.22),
    inset 0 0 18px rgba(255, 0, 255, 0.07) !important;
}

/* Surface helpers — paint the same flat near-black so layered scroll
   containers don't show slate seams. */
.surface-page,
.surface-1,
.surface-2,
.surface-3,
.surface-muted {
  background-color: #f7f7fa !important;
}
html.dark .surface-page,
html.dark .surface-1,
html.dark .surface-2,
html.dark .surface-3,
html.dark .surface-muted {
  background-color: #050510 !important;
}

/* Monospace text accent. Headings adopt JetBrains Mono / system mono
   so small text labels (build IDs, slot names) lean into the cyberpunk
   typography. */
code,
pre,
.font-mono,
.text-xs.uppercase {
  font-family: "JetBrains Mono", "Menlo", "Monaco", monospace;
}

/* Strong text in dark mode picks up a faint cyan tint so it sits on
   the near-black bg without looking flat. */
html.dark .text-strong,
html.dark h1,
html.dark h2,
html.dark h3 {
  color: #e0fbff;
  text-shadow: 0 0 4px rgba(0, 255, 255, 0.15);
}

/* Inputs — neon-stroked. Focus ring intensifies the cyan glow. */
.input {
  background: rgba(255, 255, 255, 0.6) !important;
  border: 1px solid rgba(0, 200, 220, 0.5) !important;
  box-shadow: 0 0 6px rgba(0, 200, 220, 0.18) !important;
}
html.dark .input {
  background: rgba(5, 10, 20, 0.7) !important;
  border-color: rgba(0, 255, 255, 0.55) !important;
  color: #e0fbff;
  box-shadow:
    0 0 6px rgba(0, 255, 255, 0.35),
    inset 0 0 8px rgba(0, 255, 255, 0.05) !important;
}
.input:focus {
  border-color: #00ffff !important;
  box-shadow:
    0 0 10px rgba(0, 255, 255, 0.5),
    inset 0 0 8px rgba(0, 255, 255, 0.1) !important;
}

ocean.css:
/* ============================================================================
 * Theme: ocean — Layered cards with wave-crest top edges
 * ----------------------------------------------------------------------------
 * Structurally: cards carry a translucent gradient highlight along the top
 * edge (the "wave crest"), stacked shadows so each card looks like it's
 * floating above the previous wave, and a slow horizontal drift on the
 * page gradient that mimics water flow. Not just blue — the cards
 * actually look layered.
 * ============================================================================ */

body {
  background:
    linear-gradient(135deg, #e0f2fe 0%, #cffafe 35%, #a7f3d0 100%);
  background-size: 200% 100%;
  background-attachment: fixed;
  animation: oceanFlow 24s ease-in-out infinite;
  color: #082f49;
}
html.dark body {
  background:
    linear-gradient(135deg, #042f2e 0%, #082f49 50%, #0c4a6e 100%);
  background-size: 200% 100%;
  background-attachment: fixed;
  animation: oceanFlow 24s ease-in-out infinite;
  color: #cffafe;
}
@keyframes oceanFlow {
  0%, 100% { background-position: 0% 50%; }
  50%      { background-position: 100% 50%; }
}
@media (prefers-reduced-motion: reduce) { body { animation: none !important; } }

/* Stacked-shadow recipe: three offset shadows cascade downward, creating
   the look of cards layered like waves rolling onto a beach. */
.glass {
  position: relative;
  background: rgba(165, 243, 252, 0.35) !important;
  backdrop-filter: blur(10px) saturate(150%);
  -webkit-backdrop-filter: blur(10px) saturate(150%);
  border: 1px solid rgba(34, 211, 238, 0.4);
  border-radius: 0.75rem;
  box-shadow:
    0 2px 6px rgba(8, 47, 73, 0.06),
    0 8px 18px rgba(8, 47, 73, 0.08),
    0 18px 36px rgba(8, 47, 73, 0.10);
  overflow: hidden;
  transition: box-shadow 200ms ease-out;
}
html.dark .glass {
  background: rgba(34, 211, 238, 0.06) !important;
  border-color: rgba(56, 189, 248, 0.25);
  box-shadow:
    0 2px 6px rgba(0, 0, 0, 0.25),
    0 8px 18px rgba(0, 0, 0, 0.35),
    0 18px 36px rgba(0, 0, 0, 0.5);
}

/* Wave-crest highlight along the top edge of every card. The ::before
   sits inside the card (overflow:hidden on parent), occupies the top
   third, and fades from a lighter cyan into transparent so the card
   reads as "the surface of a wave with light catching the top". */
.glass::before,
.card::before,
.glass-elevated::before,
.card-elevated::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 35%;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.45) 0%,
    rgba(165, 243, 252, 0.15) 60%,
    transparent 100%
  );
  pointer-events: none;
  z-index: 0;
}
html.dark .glass::before,
html.dark .card::before,
html.dark .glass-elevated::before,
html.dark .card-elevated::before {
  background: linear-gradient(
    180deg,
    rgba(56, 189, 248, 0.18) 0%,
    rgba(34, 211, 238, 0.08) 60%,
    transparent 100%
  );
}

/* Hover deepens the cascade so the wave swells. */
.glass:hover {
  box-shadow:
    0 4px 8px rgba(8, 47, 73, 0.08),
    0 12px 22px rgba(8, 47, 73, 0.12),
    0 24px 48px rgba(8, 47, 73, 0.14);
}
html.dark .glass:hover {
  box-shadow:
    0 4px 8px rgba(0, 0, 0, 0.3),
    0 12px 22px rgba(0, 0, 0, 0.45),
    0 24px 48px rgba(0, 0, 0, 0.6);
}

.glass-elevated {
  position: relative;
  background: rgba(207, 250, 254, 0.55) !important;
  backdrop-filter: blur(14px) saturate(170%);
  -webkit-backdrop-filter: blur(14px) saturate(170%);
  border: 1px solid rgba(34, 211, 238, 0.5);
  border-radius: 0.75rem;
  box-shadow:
    0 4px 10px rgba(8, 47, 73, 0.10),
    0 14px 26px rgba(8, 47, 73, 0.14),
    0 28px 52px rgba(8, 47, 73, 0.18);
  overflow: hidden;
}
html.dark .glass-elevated {
  background: rgba(56, 189, 248, 0.12) !important;
  border-color: rgba(56, 189, 248, 0.4);
  box-shadow:
    0 4px 10px rgba(0, 0, 0, 0.3),
    0 14px 26px rgba(0, 0, 0, 0.45),
    0 28px 52px rgba(0, 0, 0, 0.6);
}

.glass-bar {
  background: rgba(207, 250, 254, 0.7) !important;
  backdrop-filter: blur(18px) saturate(180%);
  -webkit-backdrop-filter: blur(18px) saturate(180%);
  border-bottom: 1px solid rgba(34, 211, 238, 0.35);
}
html.dark .glass-bar {
  background: rgba(8, 47, 73, 0.75) !important;
  border-color: rgba(56, 189, 248, 0.35);
}

.card, .card-elevated {
  position: relative;
  background: rgba(207, 250, 254, 0.45) !important;
  backdrop-filter: blur(10px) saturate(150%);
  -webkit-backdrop-filter: blur(10px) saturate(150%);
  border: 1px solid rgba(34, 211, 238, 0.35) !important;
  border-radius: 0.75rem !important;
  box-shadow:
    0 2px 6px rgba(8, 47, 73, 0.06),
    0 8px 18px rgba(8, 47, 73, 0.08),
    0 18px 36px rgba(8, 47, 73, 0.10) !important;
  overflow: hidden;
}
html.dark .card, html.dark .card-elevated {
  background: rgba(34, 211, 238, 0.08) !important;
  border-color: rgba(56, 189, 248, 0.28) !important;
  box-shadow:
