}
html.dark .glass-bar {
  background: rgba(20, 83, 45, 0.85) !important;
  border-color: rgba(34, 197, 94, 0.25);
}

.card {
  position: relative;
  background: #fefce8 !important;
  border: 1px solid rgba(120, 53, 15, 0.18) !important;
  border-radius: 14px 12px 16px 13px !important;
  box-shadow:
    0 1px 3px rgba(120, 53, 15, 0.08),
    0 6px 14px rgba(120, 53, 15, 0.10) !important;
  color: #14532d;
}
html.dark .card {
  background: #1c1917 !important;
