body {
  background:
    /* Petal-scatter dots — small soft pink dots randomly placed via
       a repeating SVG pattern so the page feels gently snowed-on. */
    url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='40' cy='30' r='2.5' fill='%23fbcfe8' opacity='0.6'/%3E%3Ccircle cx='180' cy='80' r='1.8' fill='%23f9a8d4' opacity='0.55'/%3E%3Ccircle cx='90' cy='180' r='2.2' fill='%23fbcfe8' opacity='0.5'/%3E%3Ccircle cx='200' cy='200' r='1.6' fill='%23f9a8d4' opacity='0.45'/%3E%3Ccircle cx='30' cy='150' r='1.4' fill='%23fbcfe8' opacity='0.55'/%3E%3Ccircle cx='130' cy='60' r='1.2' fill='%23f9a8d4' opacity='0.4'/%3E%3C/svg%3E"),
    linear-gradient(180deg, #ffffff 0%, #fdf2f8 50%, #fff7ed 100%);
