  background: rgba(255, 255, 255, 0.9) !important;
  border: 1.5px dashed rgba(244, 114, 182, 0.5) !important;
  border-radius: 0.5rem !important;
}
html.dark .input {
  background: rgba(31, 10, 26, 0.7) !important;
  border-color: rgba(244, 114, 182, 0.4) !important;
  color: #fce7f3;
}

arctic.css:
/* ============================================================================
 * Theme: arctic — Ultra-minimal hairline UI
 * ----------------------------------------------------------------------------
 * Structurally: cards have NO shadow, NO blur, NO gradient bg. They're
 * the same colour as the page, separated only by a 1px hairline border.
 * The hierarchy comes from whitespace, not chrome. Reads as a clinical
 * lab notebook or premium minimalist app.
 * ============================================================================ */

body {
  background: #f8fafc;
  color: #0f172a;
}
html.dark body {
  /* Glacial: subtly cooler than slate-modern so the two read as
     distinct themes in dark mode. Was #0f172a, identical to slate. */
  background: #0a1424;
  color: #e2e8f0;
}

/* No body::before — there's nothing to overlay. The whole point of
   arctic is to remove visual noise, not add it. */

.glass {
  background: #f8fafc !important;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  box-shadow: none;
}
html.dark .glass {
  /* Panel one step lighter than body so hairlines still read as the
     identity but the panel itself isn't invisible. Sky-cyan border
     tint preserves arctic's glacial feel. */
  background: #0f1c30 !important;
  border-color: rgba(56, 189, 248, 0.22);
}

.glass-elevated {
  background: #f8fafc !important;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  box-shadow: none;
}
html.dark .glass-elevated {
  background: #122340 !important;
  border-color: rgba(56, 189, 248, 0.3);
}

/* Hover surfaces a SLIGHTLY darker line — the only feedback. No
   transform, no shadow swell, no glow. */
.glass:hover {
  border-color: #94a3b8;
}
html.dark .glass:hover {
  border-color: #475569;
}
.glass-elevated:hover {
  border-color: #64748b;
}
html.dark .glass-elevated:hover {
  border-color: #64748b;
}

.glass-bar {
  background: rgba(248, 250, 252, 0.95) !important;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-bottom: 1px solid #e2e8f0;
}
html.dark .glass-bar {
  background: rgba(10, 20, 36, 0.92) !important;
  border-color: rgba(56, 189, 248, 0.18);
}

.card {
  background: #f8fafc !important;
  border: 1px solid #e2e8f0 !important;
  border-radius: 6px !important;
  box-shadow: none !important;
}
html.dark .card {
  background: #0f1c30 !important;
  border-color: rgba(56, 189, 248, 0.22) !important;
}
.card-elevated {
  background: #f8fafc !important;
  border: 1px solid #cbd5e1 !important;
  border-radius: 6px !important;
  box-shadow: none !important;
}
html.dark .card-elevated {
  background: #122340 !important;
  border-color: rgba(56, 189, 248, 0.3) !important;
}

.surface-page, .surface-1, .surface-2, .surface-3, .surface-muted {
  background-color: #f8fafc !important;
}
html.dark .surface-page, html.dark .surface-1, html.dark .surface-2,
html.dark .surface-3, html.dark .surface-muted {
  background-color: #0a1424 !important;
}

.chip {
  background: transparent;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
}
html.dark .chip {
  background: transparent;
  border-color: #334155;
}
.divider-soft { border-color: #e2e8f0; }
html.dark .divider-soft { border-color: #1e293b; }
.input {
  background: #ffffff !important;
  border: 1px solid #cbd5e1 !important;
  border-radius: 4px !important;
  box-shadow: none !important;
}
html.dark .input {
  background: #0f172a !important;
  border-color: #334155 !important;
  color: #e2e8f0;
}

lavender.css:
/* ============================================================================
 * Theme: lavender — Soft radial mesh gradient cards
 * ----------------------------------------------------------------------------
 * Structurally: cards carry a stack of overlapping radial gradients in
 * pastel violets / pinks, blended low-opacity so the surface looks like
 * a soft mesh of flowing colour rather than a solid panel. Body bg
 * does the same trick at larger scale. Dreamy, ethereal — like a soft
 * lava lamp.
 * ============================================================================ */

body {
  background:
    radial-gradient(ellipse at 15% 20%, rgba(196, 181, 253, 0.55), transparent 50%),
    radial-gradient(ellipse at 85% 15%, rgba(244, 114, 182, 0.35), transparent 50%),
    radial-gradient(ellipse at 60% 80%, rgba(167, 139, 250, 0.45), transparent 55%),
    linear-gradient(135deg, #faf5ff 0%, #fdf4ff 50%, #fce7f3 100%);
  background-attachment: fixed;
  color: #3b0764;
}
html.dark body {
  background:
    radial-gradient(ellipse at 15% 20%, rgba(139, 92, 246, 0.45), transparent 50%),
    radial-gradient(ellipse at 85% 15%, rgba(217, 70, 239, 0.35), transparent 50%),
    radial-gradient(ellipse at 60% 80%, rgba(167, 139, 250, 0.4), transparent 55%),
    linear-gradient(135deg, #1e1b4b 0%, #2e1065 50%, #18181b 100%);
  background-attachment: fixed;
  color: #ede9fe;
}

/* Mesh-gradient cards. Three radial gradients stacked over a base
   tint give each card a soft watercolour bloom — different parts of
   the card lean different colours. */
.glass, .card {
  background:
    radial-gradient(ellipse at 20% 25%, rgba(196, 181, 253, 0.5), transparent 55%),
    radial-gradient(ellipse at 80% 75%, rgba(244, 114, 182, 0.35), transparent 55%),
    rgba(250, 245, 255, 0.85) !important;
  border: 1px solid rgba(167, 139, 250, 0.25);
  border-radius: 1rem;
  box-shadow: 0 8px 24px rgba(76, 29, 149, 0.1);
  color: #3b0764;
}
html.dark .glass, html.dark .card {
  background:
    radial-gradient(ellipse at 20% 25%, rgba(139, 92, 246, 0.3), transparent 55%),
    radial-gradient(ellipse at 80% 75%, rgba(217, 70, 239, 0.22), transparent 55%),
    rgba(46, 16, 101, 0.55) !important;
  border-color: rgba(167, 139, 250, 0.25);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.4);
  color: #ede9fe;
}

.glass-elevated, .card-elevated {
  background:
    radial-gradient(ellipse at 30% 20%, rgba(217, 70, 239, 0.4), transparent 50%),
    radial-gradient(ellipse at 80% 80%, rgba(139, 92, 246, 0.5), transparent 55%),
    rgba(253, 244, 255, 0.9) !important;
  border: 1px solid rgba(167, 139, 250, 0.35);
  border-radius: 1rem;
  box-shadow: 0 14px 36px rgba(76, 29, 149, 0.16);
  color: #3b0764;
}
html.dark .glass-elevated, html.dark .card-elevated {
  background:
    radial-gradient(ellipse at 30% 20%, rgba(217, 70, 239, 0.32), transparent 50%),
    radial-gradient(ellipse at 80% 80%, rgba(139, 92, 246, 0.36), transparent 55%),
    rgba(46, 16, 101, 0.65) !important;
  border-color: rgba(167, 139, 250, 0.32);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.5);
}

.glass:hover, .card:hover {
  box-shadow: 0 12px 30px rgba(76, 29, 149, 0.16);
}
html.dark .glass:hover, html.dark .card:hover {
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.5);
}

.glass-bar {
  background:
    radial-gradient(ellipse at 50% 100%, rgba(196, 181, 253, 0.45), transparent 60%),
    rgba(250, 245, 255, 0.85) !important;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid rgba(167, 139, 250, 0.25);
}
html.dark .glass-bar {
  background:
    radial-gradient(ellipse at 50% 100%, rgba(139, 92, 246, 0.3), transparent 60%),
    rgba(30, 27, 75, 0.85) !important;
  border-color: rgba(167, 139, 250, 0.25);
}

.surface-page, .surface-1, .surface-2, .surface-3, .surface-muted {
  background-color: rgba(250, 245, 255, 0.5) !important;
}
html.dark .surface-page, html.dark .surface-1, html.dark .surface-2,
html.dark .surface-3, html.dark .surface-muted {
  background-color: rgba(30, 27, 75, 0.6) !important;
}

.chip {
  background: rgba(196, 181, 253, 0.25);
  border: 1px solid rgba(167, 139, 250, 0.35);
  border-radius: 9999px;
}
html.dark .chip {
  background: rgba(139, 92, 246, 0.18);
  border-color: rgba(167, 139, 250, 0.35);
}
.divider-soft { border-color: rgba(76, 29, 149, 0.1); }
html.dark .divider-soft { border-color: rgba(167, 139, 250, 0.2); }
.input {
  background: rgba(255, 255, 255, 0.7) !important;
  border-color: rgba(167, 139, 250, 0.4) !important;
}
html.dark .input {
  background: rgba(30, 27, 75, 0.6) !important;
  border-color: rgba(167, 139, 250, 0.4) !important;
  color: #ede9fe;
}

rose-gold.css:
/* ============================================================================
 * Theme: rose-gold — Brushed-metal sheen, copper top edge
 * ----------------------------------------------------------------------------
 * Structurally: cards have a vertical multi-stop gradient that mimics
 * brushed rose-gold metal — narrow alternating warm tones running
 * top to bottom. A bright copper highlight stripe along the top edge
 * (1.5px ::before) catches the light. Premium, luxurious, jewellery-
 * counter feel.
 * ============================================================================ */

body {
  background: linear-gradient(135deg, #fff7ed 0%, #fef2f2 50%, #fefce8 100%);
  background-attachment: fixed;
  color: #500724;
}
html.dark body {
  background: linear-gradient(135deg, #1c0808 0%, #422006 50%, #1c1917 100%);
  background-attachment: fixed;
  color: #fce7f3;
}

/* Brushed-metal vertical gradient. Each stop is a slightly different
   rose/gold tone so the strip "shimmers" subtly when the eye runs
   across it. */
.glass, .card {
  position: relative;
  background: linear-gradient(
    180deg,
    #fef3c7 0%,
    #fde2cf 18%,
    #f5d0c5 38%,
    #fde2cf 60%,
    #fef3c7 78%,
    #fde9d4 100%
  ) !important;
  border: 1px solid rgba(180, 83, 9, 0.3);
  border-radius: 0.75rem;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.6) inset,
    0 6px 18px rgba(180, 83, 9, 0.18);
  color: #500724;
  overflow: hidden;
}
html.dark .glass, html.dark .card {
  background: linear-gradient(
    180deg,
    #4a0d0d 0%,
    #5b2519 18%,
    #422006 38%,
    #5b2519 60%,
    #4a0d0d 78%,
    #3f1d1d 100%
  ) !important;
  border-color: rgba(244, 114, 182, 0.3);
  box-shadow:
    0 1px 0 rgba(244, 114, 182, 0.15) inset,
    0 6px 22px rgba(0, 0, 0, 0.5);
  color: #fce7f3;
}

/* Copper highlight stripe — a bright thin line along the top edge that
   reads as light catching the metal. */
.glass::before, .card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1.5px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(217, 119, 6, 0.7) 20%,
    rgba(251, 191, 36, 0.9) 50%,
    rgba(217, 119, 6, 0.7) 80%,
    transparent 100%
  );
  pointer-events: none;
}
html.dark .glass::before, html.dark .card::before {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(244, 114, 182, 0.6) 20%,
    rgba(251, 191, 36, 0.8) 50%,
    rgba(244, 114, 182, 0.6) 80%,
    transparent 100%
  );
}

.glass:hover, .card:hover {
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    0 10px 26px rgba(180, 83, 9, 0.25);
}
html.dark .glass:hover, html.dark .card:hover {
  box-shadow:
    0 1px 0 rgba(244, 114, 182, 0.2) inset,
    0 10px 30px rgba(0, 0, 0, 0.6);
}

.glass-elevated, .card-elevated {
  position: relative;
  background: linear-gradient(
    180deg,
    #fef3c7 0%,
    #fbcfe8 25%,
    #fda4af 50%,
    #fbcfe8 75%,
    #fef3c7 100%
  ) !important;
  border: 1px solid rgba(190, 24, 93, 0.35);
  border-radius: 0.75rem;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    0 12px 28px rgba(190, 24, 93, 0.25);
  overflow: hidden;
}
html.dark .glass-elevated, html.dark .card-elevated {
  background: linear-gradient(
    180deg,
    #500724 0%,
    #831843 25%,
    #9d174d 50%,
    #831843 75%,
    #500724 100%
  ) !important;
  border-color: rgba(244, 114, 182, 0.35);
  box-shadow:
    0 1px 0 rgba(244, 114, 182, 0.2) inset,
    0 12px 32px rgba(0, 0, 0, 0.55);
}

.glass-bar {
  background: linear-gradient(180deg, rgba(255, 247, 237, 0.95), rgba(254, 243, 199, 0.85)) !important;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-bottom: 1px solid rgba(180, 83, 9, 0.3);
}
html.dark .glass-bar {
  background: linear-gradient(180deg, rgba(28, 8, 8, 0.95), rgba(66, 32, 6, 0.88)) !important;
  border-color: rgba(244, 114, 182, 0.3);
}

.surface-page, .surface-1, .surface-2, .surface-3, .surface-muted {
  background-color: rgba(255, 247, 237, 0.5) !important;
}
html.dark .surface-page, html.dark .surface-1, html.dark .surface-2,
html.dark .surface-3, html.dark .surface-muted {
  background-color: rgba(28, 8, 8, 0.6) !important;
}

.chip {
  background: linear-gradient(180deg, #fef3c7, #fde2cf);
  border: 1px solid rgba(180, 83, 9, 0.35);
  border-radius: 9999px;
}
html.dark .chip {
  background: linear-gradient(180deg, #4a0d0d, #422006);
  border-color: rgba(244, 114, 182, 0.35);
}
.divider-soft { border-color: rgba(180, 83, 9, 0.18); }
html.dark .divider-soft { border-color: rgba(244, 114, 182, 0.22); }
.input {
  background: rgba(255, 255, 255, 0.7) !important;
  border-color: rgba(180, 83, 9, 0.35) !important;
}
html.dark .input {
  background: rgba(28, 8, 8, 0.6) !important;
  border-color: rgba(244, 114, 182, 0.35) !important;
  color: #fce7f3;
}

copper.css:
/* ============================================================================
 * Theme: copper — Embossed / stamped with metallic bevel
 * ----------------------------------------------------------------------------
 * Structurally: cards look pressed into the surface — inset shadow at
 * the bottom-right, bright copper highlight at the top-left, like a
 * metal seal stamped into a leather page. Slightly different from
 * neumorphism: the bg is warm tan (not neutral grey) and the
 * highlight is genuine copper, not pure white.
 * ============================================================================ */

body {
  background: #f5e6d3;
  color: #3d1d05;
}
html.dark body {
  background: #1a0f08;
  color: #f5e6d3;
}

.glass, .card {
  background: #f5e6d3 !important;
  border: 1px solid rgba(180, 83, 9, 0.15) !important;
  border-radius: 0.5rem;
  box-shadow:
    /* Top-left: bright copper highlight */
    -3px -3px 6px rgba(255, 245, 230, 0.85),
    /* Bottom-right: dark embossed shadow */
    4px 4px 10px rgba(120, 53, 15, 0.25),
    /* Inset thin bright stripe at the very top — copper edge */
    inset 0 1px 0 rgba(217, 119, 6, 0.4);
  color: #3d1d05;
  transition: box-shadow 200ms ease-out;
}
html.dark .glass, html.dark .card {
  background: #2a1a10 !important;
  border-color: rgba(217, 119, 6, 0.25) !important;
  box-shadow:
    -3px -3px 6px rgba(180, 83, 9, 0.12),
    4px 4px 10px rgba(0, 0, 0, 0.6),
    inset 0 1px 0 rgba(217, 119, 6, 0.35);
  color: #f5e6d3;
}

/* Hover: shrink the bevel — like a button being pressed lightly. The
   shadows pull in toward the card outline. */
.glass:hover, .card:hover {
  box-shadow:
    -2px -2px 4px rgba(255, 245, 230, 0.85),
    2px 2px 6px rgba(120, 53, 15, 0.25),
    inset 0 1px 0 rgba(217, 119, 6, 0.5);
}
html.dark .glass:hover, html.dark .card:hover {
  box-shadow:
    -2px -2px 4px rgba(180, 83, 9, 0.15),
    2px 2px 6px rgba(0, 0, 0, 0.6),
    inset 0 1px 0 rgba(217, 119, 6, 0.45);
}

/* Active: full inset — the card looks fully pressed in. */
.glass:active, .card:active {
  box-shadow:
    inset 3px 3px 6px rgba(120, 53, 15, 0.3),
    inset -2px -2px 5px rgba(255, 245, 230, 0.7);
}
html.dark .glass:active, html.dark .card:active {
  box-shadow:
    inset 3px 3px 6px rgba(0, 0, 0, 0.65),
    inset -2px -2px 5px rgba(180, 83, 9, 0.18);
}

.glass-elevated, .card-elevated {
  background: #f5e6d3 !important;
  border: 1px solid rgba(180, 83, 9, 0.2) !important;
  border-radius: 0.5rem;
  box-shadow:
    -5px -5px 10px rgba(255, 245, 230, 0.9),
    6px 6px 14px rgba(120, 53, 15, 0.3),
    inset 0 1.5px 0 rgba(217, 119, 6, 0.5);
  color: #3d1d05;
}
html.dark .glass-elevated, html.dark .card-elevated {
  background: #2a1a10 !important;
  border-color: rgba(217, 119, 6, 0.3) !important;
  box-shadow:
    -5px -5px 10px rgba(180, 83, 9, 0.16),
    6px 6px 14px rgba(0, 0, 0, 0.7),
    inset 0 1.5px 0 rgba(217, 119, 6, 0.45);
}

.glass-bar {
  background: #f5e6d3 !important;
  border: none;
  box-shadow:
    0 4px 10px rgba(120, 53, 15, 0.18),
    inset 0 -1px 0 rgba(217, 119, 6, 0.35);
}
html.dark .glass-bar {
  background: #1a0f08 !important;
  box-shadow:
    0 4px 10px rgba(0, 0, 0, 0.6),
    inset 0 -1px 0 rgba(217, 119, 6, 0.4);
}

.surface-page, .surface-1, .surface-2, .surface-3, .surface-muted {
  background-color: #f5e6d3 !important;
}
html.dark .surface-page, html.dark .surface-1, html.dark .surface-2,
html.dark .surface-3, html.dark .surface-muted {
  background-color: #1a0f08 !important;
}

.chip {
  background: #f5e6d3;
  border: none;
  border-radius: 9999px;
  box-shadow:
    inset 2px 2px 4px rgba(120, 53, 15, 0.2),
    inset -2px -2px 4px rgba(255, 245, 230, 0.8);
}
html.dark .chip {
  background: #2a1a10;
  box-shadow:
    inset 2px 2px 4px rgba(0, 0, 0, 0.6),
    inset -2px -2px 4px rgba(217, 119, 6, 0.18);
}
.divider-soft { border-color: rgba(120, 53, 15, 0.2); }
html.dark .divider-soft { border-color: rgba(217, 119, 6, 0.25); }
.input {
  background: #f5e6d3 !important;
  border: none !important;
  border-radius: 0.5rem !important;
  box-shadow:
    inset 3px 3px 5px rgba(120, 53, 15, 0.22),
    inset -3px -3px 5px rgba(255, 245, 230, 0.85) !important;
}
html.dark .input {
  background: #2a1a10 !important;
  color: #f5e6d3;
  box-shadow:
    inset 3px 3px 5px rgba(0, 0, 0, 0.65),
    inset -3px -3px 5px rgba(217, 119, 6, 0.16) !important;
}

emerald.css:
/* ============================================================================
 * Theme: emerald — Floating islands with deep rounded corners
 * ----------------------------------------------------------------------------
 * Structurally: cards have very large rounded corners (2rem), strong
 * directional drop shadows, and visibly hover above the page like
 * floating platforms. No glass blur — solid jewel-tone backgrounds in
 * deep emerald / mint. The shadow distance + offset is exaggerated so
 * each card reads as suspended in mid-air.
 * ============================================================================ */

body {
  background: linear-gradient(180deg, #ecfdf5 0%, #d1fae5 50%, #a7f3d0 100%);
  background-attachment: fixed;
  color: #064e3b;
}
html.dark body {
  background: linear-gradient(180deg, #022c22 0%, #064e3b 50%, #022c22 100%);
  background-attachment: fixed;
  color: #d1fae5;
}

.glass, .card {
  background: #ffffff !important;
  border: none !important;
  border-radius: 2rem !important;
  /* Deep, downward-skewed shadow — the card is hovering. */
  box-shadow:
    0 20px 50px -12px rgba(6, 78, 59, 0.25),
    0 8px 20px -6px rgba(6, 78, 59, 0.15) !important;
  color: #064e3b;
  transition: transform 250ms ease-out, box-shadow 250ms ease-out;
}
html.dark .glass, html.dark .card {
  background: #064e3b !important;
  border: none !important;
  box-shadow:
    0 20px 50px -12px rgba(0, 0, 0, 0.6),
    0 8px 20px -6px rgba(0, 0, 0, 0.4) !important;
  color: #a7f3d0;
}

/* Hover: lift even higher. Cards visibly leave the page. */
.glass:hover, .card:hover {
  transform: translateY(-4px);
  box-shadow:
    0 28px 60px -12px rgba(6, 78, 59, 0.3),
    0 12px 28px -6px rgba(6, 78, 59, 0.2) !important;
}
html.dark .glass:hover, html.dark .card:hover {
  transform: translateY(-4px);
  box-shadow:
    0 28px 60px -12px rgba(0, 0, 0, 0.7),
    0 12px 28px -6px rgba(0, 0, 0, 0.5) !important;
}

.glass-elevated, .card-elevated {
  background: linear-gradient(180deg, #ecfdf5 0%, #d1fae5 100%) !important;
  border: none !important;
  border-radius: 2rem !important;
  box-shadow:
    0 28px 60px -12px rgba(5, 150, 105, 0.3),
    0 12px 28px -6px rgba(5, 150, 105, 0.18) !important;
  color: #022c22;
}
html.dark .glass-elevated, html.dark .card-elevated {
  background: linear-gradient(180deg, #047857 0%, #064e3b 100%) !important;
  box-shadow:
    0 28px 60px -12px rgba(0, 0, 0, 0.7),
    0 12px 28px -6px rgba(0, 0, 0, 0.5) !important;
  color: #a7f3d0;
}

.glass-bar {
  background: rgba(255, 255, 255, 0.85) !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(5, 150, 105, 0.2);
  border-radius: 0;
}
html.dark .glass-bar {
