  box-shadow: 0 4px 10px -2px rgba(0, 0, 0, 0.4);
}
.divider-soft { border-color: rgba(5, 150, 105, 0.18); }
html.dark .divider-soft { border-color: rgba(5, 150, 105, 0.3); }
